From: Codex

Read-only diagnostic for you to paste/run in Unreal Python. It logs `RESCUE396` lines; it does not modify/save assets or actors, recompile, spawn, or delete. I reviewed the script statically; I cannot execute Unreal here. Version-specific unavailable properties are caught and logged. Please return its Output Log plus the screenshots/console queries above.

IMPORTANT: Open M_LP2Decal in the Material Editor first, without editing it. Epic's UE5.3 API documents get_material_property_input_node as querying an active Material Editor. If not open, null outputs are inconclusive. Connected output nodes alone also do not validate the entire graph; we still need the alpha wiring screenshot. API: https://dev.epicgames.com/documentation/en-us/unreal-engine/python-api/class/MaterialEditingLibrary?application_version=5.3

```python
# Tower9 rescue #396: read-only inventory; run in Unreal Python.
# Does not save, recompile, set properties, spawn, or delete anything.
import unreal
MEL = unreal.MaterialEditingLibrary
def report(label, fn):
    try:
        value = fn()
        if isinstance(value, unreal.Object):
            value = value.get_path_name()
        unreal.log("RESCUE396 " + label + " = " + str(value))
        return value
    except Exception as exc:
        unreal.log_warning("RESCUE396 " + label + " unavailable: " + str(exc))
report("engine_version", unreal.SystemLibrary.get_engine_version)
actors = unreal.get_editor_subsystem(unreal.EditorActorSubsystem).get_all_level_actors()
materials = {}
count = 0
for actor in actors:
    if not actor.get_actor_label().startswith("Tower9_Decal_"):
        continue
    for comp in actor.get_components_by_class(unreal.DecalComponent):
        count += 1
        mi = comp.get_decal_material()
        label = actor.get_actor_label()
        report(label + ".material", lambda: mi)
        report(label + ".size", lambda: comp.get_editor_property("decal_size"))
        report(label + ".scale", comp.get_world_scale)
        report(label + ".rotation", comp.get_world_rotation)
        if mi:
            materials[mi.get_path_name()] = mi
unreal.log("RESCUE396 component_count = " + str(count))
for path, mi in sorted(materials.items()):
    report(path + ".parent", lambda: mi.get_editor_property("parent"))
    for name in ("BaseColor", "ORM", "Normal"):
        report(path + "." + name, lambda name=name: MEL.get_material_instance_texture_parameter_value(mi, name))
    for name in ("Opacity", "NormalStrength"):
        report(path + "." + name, lambda name=name: MEL.get_material_instance_scalar_parameter_value(mi, name))
    report(path + ".Tint", lambda: MEL.get_material_instance_vector_parameter_value(mi, "Tint"))
master = unreal.load_asset("/Game/CastleDefender/Environment/Decals/M_LP2Decal")
if master:
    for prop in ("material_domain", "blend_mode"):
        report("master." + prop, lambda prop=prop: master.get_editor_property(prop))
    for name in ("MP_BASE_COLOR", "MP_OPACITY", "MP_NORMAL", "MP_ROUGHNESS"):
        report("master." + name, lambda name=name: MEL.get_material_property_input_node(master, getattr(unreal.MaterialProperty, name)))

```

